function paymentAmount(personId,periodId){return state.payments.filter(x=>x.personId===personId&&x.periodId===periodId).reduce((n,x)=>n+Number(x.amount||0),0)}
function protectedPayment(payment){return !!payment.registryId||String(payment.author||'').startsWith('Шеф')||String(payment.source||'').startsWith('Подотчёт №')}
