function monthKeyFromPeriodText(value){const names={января:'01',февраля:'02',марта:'03',апреля:'04',мая:'05',июня:'06',июля:'07',августа:'08',сентября:'09',октября:'10',ноября:'11',декабря:'12'},text=String(value||'').toLowerCase(),name=Object.keys(names).find(x=>text.includes(x)),year=text.match(/\b(20\d{2})\b/)?.[1];return name&&year?`${year}-${names[name]}`:''}
function currentAccountingMonthKey(){return String(currentPeriodTo||currentPeriodFrom||'').slice(0,7)}
function dateInRuRange(value,from,to){const date=ruToIso(value),start=ruToIso(from),end=ruToIso(to);return !!date&&!!start&&!!end&&date>=start&&date<=end}
function inCurrentPeriod(value){const iso=ruToIso(value);return iso>=currentPeriodFrom&&iso<=currentPeriodTo}
