function calcPeriodLabel(from,to){const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'],a=new Date(`${from}T12:00:00`),b=new Date(`${to}T12:00:00`);if(Number.isNaN(a.getTime())||Number.isNaN(b.getTime()))return currentPeriod;const same=a.getMonth()===b.getMonth()&&a.getFullYear()===b.getFullYear();return same?`${a.getDate()}–${b.getDate()} ${months[b.getMonth()]} ${b.getFullYear()}`:`${a.getDate()} ${months[a.getMonth()]}–${b.getDate()} ${months[b.getMonth()]} ${b.getFullYear()}`}
function minutes(t){if(!t)return null;const [h,m]=t.split(':').map(Number);return h*60+m}
