function timesheetPage(){const allRows=weekRows(),entityRows=currentEntity==='Все ООО'?allRows:allRows.filter(r=>r.p.legalEntity===currentEntity||r.shifts.some(s=>s.legalEntity===currentEntity)),rows=currentEmployment==='Все оформления'?entityRows:entityRows.filter(r=>employment(r.p)===currentEmployment),ready=rows.filter(r=>r.ok),errors=rows.filter(r=>r.shifts.length&&!r.ok),total=ready.reduce((n,r)=>n+r.total,0),balance=ready.reduce((n,r)=>n+Math.max(0,r.balance),0),byType=t=>ready.filter(r=>employment(r.p)===t).reduce((n,r)=>n+r.total,0),scope=currentLocation==='Все площадки'?(currentEntity==='Все ООО'?'Все юрлица':currentEntity):`${currentLocation} · ${currentEntity}`;return `<div class="page-title-row"><div>${kitchenBack()}<div class="eyebrow">Кухня · ${currentPeriod}</div><h1 class="page-title">Расчётная ведомость</h1></div><div class="actions"><button class="btn" data-action="accounting-person">+ Добавить сотрудника</button><button class="btn" data-action="export">⇩ Excel по месяцу</button><button class="btn primary" data-action="open-registers">Сформировать выплату</button></div></div>${weekFilters()}${accountingOverview(ready,total,balance,errors,byType,scope)}<div class="panel ledger-panel"><div class="ledger-toolbar"><div class="view-tabs"><button class="view-tab ${currentView==='statement'?'active':''}" data-view="statement">Расчётная ведомость <span class="soft-count">${ready.length}</span></button><button class="view-tab ${currentView==='attention'?'active':''}" data-view="attention">Требуют исправления <span class="count">${errors.length}</span></button><button class="view-tab ${currentView==='registers'?'active':''}" data-view="registers">Реестры выплат <span class="soft-count">${state.registries.length}</span></button></div><button class="btn primary create-period-btn" data-action="create-payment-period">+ Период выплаты</button></div>${currentView==='attention'?errorsTable(errors):currentView==='registers'?registryTable():statementTable(ready)}<div class="panel-foot"><span>${currentView==='statement'?'Часы и смены открываются в карточке сотрудника':`Период: ${currentPeriod}`} · ${modeLabel(true)}</span></div></div>`}
function dayCell(r,date){const ss=r.shifts.filter(s=>s.date===date);return ss.length?ss.map(s=>`<button class="hours-cell" data-shift="${s.id}" title="Открыть смену">${hours(s)?.toLocaleString('ru-RU')||'—'} ч</button>`).join(''):'<span class="dash">—</span>'}
function rowStatus(r){if(r.balance<0)return status('Переплата / аванс','warn');if(r.balance===0&&r.paid>0)return status('Выплачен','good');if(state.registries.some(x=>x.status!=='Выплачен'&&x.people?.includes(r.p.id)&&(x.accountingMonth||monthKeyFromRuDate(x.to))===currentAccountingMonthKey()))return status('В реестре','warn');return status('Готов к выплате','good')}
function statementTable(rows){if(!rows.length)return empty('Готовых расчётов пока нет','Сотрудники появятся после закрытия смен, назначения ставок и исправления ошибок.');const periods=(state.paymentPeriods||[]).filter(p=>paymentPeriodInCurrentMonth(p)&&(!p.locked||p.visible)),periodHeads=periods.map(p=>`<th class="payment-period-head ${p.locked?'locked':''}"><span>${p.type}</span><small>${p.from===p.to?p.from:`${p.from.slice(0,5)}–${p.to}`}</small>${p.locked?'<i title="Период закрыт">✓ только просмотр</i>':`<button data-action="close-payment-period" data-id="${p.id}" title="Закрыть период">Закрыть</button>`}</th>`).join('');return `<div class="ledger-help"><span><b>Начислено</b> = труд</span><span><b>Итого</b> = начислено + такси + премии и анимации − штрафы</span><span>Суммы вводятся во всех открытых периодах прямо в строках</span></div><div class="table-wrap statement-scroll"><table class="data-table ledger-table accounting-model"><thead><tr><th><input type="checkbox" data-check-all aria-label="Выбрать всех"></th><th>Должность</th><th>ФИО</th><th>Ставка</th><th>Начислено</th><th>Такси</th><th>Премии и анимации</th><th>Штрафы</th><th>Итого</th>${periodHeads}<th>Итого выплачено</th><th>К выплате</th><th>Статус</th></tr></thead><tbody>${rows.map(r=>`<tr data-ledger-row data-person-name="${r.p.name.toLowerCase()}"><td><input type="checkbox" data-pay-person="${r.p.id}" ${r.balance<=0?'disabled':''}></td><td><b>${r.p.position}</b><div class="subline">${employment(r.p)} · ${r.p.type}</div></td><td><button class="person-link" data-person="${r.p.id}">${r.p.name}</button>${r.p.source==='accounting'?'<div class="subline">Без табеля охраны</div>':''}</td><td>${r.p.payType==='Оклад'?'Оклад':r.p.payType==='Фиксированная сумма за неделю'?'За неделю':r.p.type==='Вызывной'&&employment(r.p)==='Наличные'?'По сменам':money(r.p.rate)}</td><td><b>${money(r.base)}</b></td><td><label class="inline-money"><input type="number" min="0" step="100" value="${r.taxi||''}" placeholder="0" data-taxi-person="${r.p.id}"><span>₽</span></label></td><td><button class="amount-detail ${r.plannedBonus?'positive':''}" data-person="${r.p.id}">${r.plannedBonus?`+${money(isClosingPeriod()?r.bonus:r.plannedBonus)}`:'—'}</button>${r.plannedBonus&&!isClosingPeriod()?'<div class="subline">Запланировано</div>':''}</td><td><button class="amount-detail ${r.penalty?'negative':''}" data-person="${r.p.id}">${r.penalty?`−${money(r.penalty)}`:'—'}</button></td><td><b>${money(r.total)}</b></td>${periods.map(p=>{const amount=paymentAmount(r.p.id,p.id);return `<td class="payment-cell ${p.locked?'locked':''}">${p.locked?`<b title="Закрытый период">${money(amount)}</b>`:`<label class="inline-money payment-input"><input type="number" min="0" step="100" value="${amount||''}" placeholder="0" data-payment-person="${r.p.id}" data-payment-period="${p.id}"><span>₽</span></label>`}</td>`}).join('')}<td><b>${money(r.paid)}</b></td><td><b class="${r.balance<0?'negative':r.balance===0?'positive':''}">${money(r.balance)}</b></td><td>${rowStatus(r)}</td></tr>`).join('')}</tbody></table></div>`}
function errorsTable(rows){if(!rows.length)return empty('Ошибок нет','Все сотрудники с закрытыми и проверенными сменами доступны в расчёте.');return `<div class="table-wrap"><table class="data-table compact"><thead><tr><th>Сотрудник</th><th>Площадка</th><th>ООО</th><th>Проблема</th><th>Что требуется</th><th></th></tr></thead><tbody>${rows.map(r=>r.errorShifts.map(s=>`<tr><td><button class="person-link" data-person="${r.p.id}">${r.p.name}</button></td><td>${s.location}</td><td>${s.legalEntity}</td><td>${status(s.status,'bad')}</td><td>${!s.exit?'Охране отметить уход':!rateOf(s)?'Назначить ставку':s.rateReview?'Бухгалтерии подтвердить базовую ставку':'Проверить расхождение'}</td><td><button class="btn small" data-shift="${s.id}">Открыть смену</button></td></tr>`).join('')).join('')}</tbody></table></div>`}
function currentRegistries(){return state.registries.filter(r=>(r.accountingMonth||monthKeyFromRuDate(r.to))===currentAccountingMonthKey())}
function registryTable(){const registries=currentRegistries();if(!registries.length)return empty(`Реестры за ${periodMonth().toLowerCase()} ещё не сформированы`,'Выберите готовых сотрудников и сформируйте отдельные ведомости для ТК, СЗ и наличных.','<button class="btn primary" data-action="open-registers">Сформировать выплату</button>');return `<div class="registry-grid">${registries.map(r=>{const paid=r.status==='Выплачен';return `<article class="registry-card"><div><span class="tag green">${r.engagement}</span><h3>Ведомость №${r.id}</h3><p>${r.period} · ${r.people.length} чел.</p></div><strong>${money(r.amount)}</strong><div class="registry-actions"><button class="btn small" data-action="download-registry" data-id="${r.id}">⇩ Excel</button><button class="btn small primary" data-action="mark-paid" data-id="${r.id}" ${paid?'disabled':''}>${paid?'✓ Выплачено':'Провести выплату'}</button></div><div class="muted">Получатель: ${r.recipient}</div><div class="registry-note ${paid?'paid':''}">${paid?'Суммы проведены по каждому сотруднику и видны в расчётной ведомости.':'После фактической оплаты нажмите «Провести выплату» — суммы попадут каждому сотруднику.'}</div></article>`}).join('')}</div>`}
function shiftTable(rows){if(!rows.length)return empty('Смен пока нет','Переключитесь на роль «Охрана» и начните с регистрации сотрудника.','<button class="btn primary" onclick="switchRole(\'Охрана\')">Перейти к охране</button>');return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Сотрудник</th><th>Должность</th><th>Тип</th><th>Оформление</th><th>Присутствие</th><th>Рабочее время</th><th>К оплате</th><th>Ставка</th><th>Начислено</th><th>Выплачено</th><th>Статус</th></tr></thead><tbody>${rows.map(s=>`<tr class="clickable" data-shift="${s.id}"><td>${s.date}</td><td><b>${person(s.personId).name}</b></td><td>${s.position}</td><td><span class="tag ${s.type==='Вызывной'?'amber':''}">${s.type}</span></td><td><span class="tag green">${employment(s)}</span></td><td>${s.entry}–${s.exit||'…'}</td><td>${s.workStart?`${s.workStart}–${s.workEnd}`:'—'}</td><td>${hours(s)==null?'—':`${hours(s).toLocaleString('ru-RU')} ч`}</td><td>${money(rateOf(s))}</td><td>${money(accrued(s))}</td><td>${money(s.paid)}</td><td>${status(s.status,tone(s))}</td></tr>`).join('')}</tbody></table></div>`}
function peopleTable(){if(!state.people.length)return empty('Сотрудников пока нет','Охрана зарегистрирует первого сотрудника.');return `<div class="table-wrap"><table class="data-table compact"><thead><tr><th>Сотрудник</th><th>Должность</th><th>Тип</th><th>Оформление</th><th>Смены</th><th>Часы</th><th>Начислено</th><th>Выплачено</th><th>Остаток</th></tr></thead><tbody>${state.people.map(p=>{const ss=state.shifts.filter(s=>s.personId===p.id),a=ss.reduce((n,s)=>n+(accrued(s)||0),0),pd=ss.reduce((n,s)=>n+(s.paid||0),0);return `<tr><td><b>${p.name}</b></td><td>${p.position}</td><td>${p.type}</td><td><span class="tag green">${employment(p)}</span></td><td>${ss.length}</td><td>${ss.reduce((n,s)=>n+(hours(s)||0),0)}</td><td>${money(a)}</td><td>${money(pd)}</td><td>${money(a-pd)}</td></tr>`}).join('')}</tbody></table></div>`}
function accrualsPage(){const rows=state.people.map(p=>{const ss=state.shifts.filter(s=>s.personId===p.id),h=ss.reduce((n,s)=>n+(hours(s)||0),0),base=ss.reduce((n,s)=>n+(accrued(s)||0),0),adj=state.adjustments.filter(a=>a.personId===p.id).reduce((n,a)=>n+(a.type==='Штраф'?-a.amount:a.amount),0);return {p,h,base,adj,total:base+adj}});return `<div class="page-title-row"><h1 class="page-title">Начисления</h1><div class="actions"><button class="btn" data-action="bonus">+ Премия</button><button class="btn" data-action="penalty">− Штраф</button><button class="btn primary" data-action="calculate">Рассчитать неделю</button></div></div>${filters()}${metrics([['Сотрудники',state.people.length],['Труд',money(rows.reduce((n,r)=>n+r.base,0))],['Доплаты',money(state.adjustments.filter(a=>a.type==='Премия').reduce((n,a)=>n+a.amount,0))],['Удержания',money(state.adjustments.filter(a=>a.type==='Штраф').reduce((n,a)=>n+a.amount,0))]])}<div class="panel">${rows.length?`<div class="table-wrap"><table class="data-table compact"><thead><tr><th>Сотрудник</th><th>Тип</th><th>Оформление сейчас</th><th>Часы</th><th>Ставка</th><th>Труд</th><th>Корректировки</th><th>Итого</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.p.name}</b></td><td>${r.p.type}</td><td><span class="tag green">${employment(r.p)}</span></td><td>${r.h.toLocaleString('ru-RU')} ч</td><td>${r.p.type==='Вызывной'&&employment(r.p)==='Наличные'?'По сменам':money(r.p.rate)}</td><td>${money(r.base)}</td><td>${money(r.adj)}</td><td><b>${money(r.total)}</b></td><td><button class="btn small" data-action="edit-rate" data-id="${r.p.id}">Оформление и ставка</button></td></tr>`).join('')}</tbody></table></div>`:empty('Начислять пока некому','Сначала зарегистрируйте сотрудника через роль «Охрана».')}</div>`}
function paymentsPage(){return `<div class="page-title-row"><h1 class="page-title">Выплаты</h1><div class="actions"><button class="btn" data-action="export">⇩ Выгрузить</button><button class="btn primary" data-action="payment">+ Зарегистрировать выплату</button></div></div>${filters()}${metrics([['Выплат',state.payments.length],['Выплачено',money(state.payments.reduce((n,p)=>n+p.amount,0))],['Шефом',money(state.payments.filter(p=>p.author.startsWith('Шеф')).reduce((n,p)=>n+p.amount,0))],['Расхождения',state.payments.filter(p=>p.status==='Расхождение').length,'red']])}<div class="panel">${state.payments.length?`<div class="table-wrap"><table class="data-table compact"><thead><tr><th>Дата</th><th>Сотрудник</th><th>Тип</th><th>Сумма</th><th>Зафиксировал</th><th>Источник</th><th>Статус</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td>${p.date}</td><td><b>${person(p.personId).name}</b></td><td>${p.type}</td><td>${money(p.amount)}</td><td>${p.author}</td><td>${p.source}</td><td>${status(p.status,p.status==='Расхождение'?'bad':'good')}</td></tr>`).join('')}</tbody></table></div>`:empty('Выплат пока нет','Выплату вызывному фиксирует шеф, обычному сотруднику — бухгалтерия.')}</div>`}
function advancesPage(){return `<div class="page-title-row"><div>${kitchenBack()}<div class="eyebrow">Кухня</div><h1 class="page-title">Подотчёты</h1></div><button class="btn primary" data-action="advance">+ Выдать подотчёт</button></div>${filters()}${metrics([['Подотчётов',state.advances.length],['Выдано',money(state.advances.reduce((n,a)=>n+a.issued,0))],['Использовано',money(state.advances.reduce((n,a)=>n+a.spent,0))],['Остаток',money(state.advances.reduce((n,a)=>n+a.issued-a.spent,0))]])}<div class="panel">${state.advances.length?`<div class="table-wrap"><table class="data-table compact"><thead><tr><th>№</th><th>Шеф</th><th>Неделя</th><th>Выдано</th><th>Расход</th><th>Остаток</th><th>Статус</th></tr></thead><tbody>${state.advances.map(a=>`<tr><td>№${a.id}</td><td>${a.chef}</td><td>${a.week}</td><td>${money(a.issued)}</td><td>${money(a.spent)}</td><td>${money(a.issued-a.spent)}</td><td>${status(a.status,a.status==='Закрыт'?'good':'warn')}</td></tr>`).join('')}</tbody></table></div>`:empty('Подотчётов пока нет','Выдайте шефу недельную сумму для расчёта с вызывными.')}</div>`}
function reportsPage(){const cards=[['Табель часов','Точные отметки, рабочее и оплачиваемое время'],['Начисления','Ставки, премии и штрафы'],['Выплаты','Все выплаты и остатки'],['Подотчёты','Движение средств по каждому шефу'],['Задолженность','Неоплаченные остатки исходных месяцев'],['История исправлений','Кто, когда и почему менял данные']];return `<div class="page-title-row"><div>${kitchenBack()}<div class="eyebrow">Кухня</div><h1 class="page-title">Отчёты</h1></div></div>${filters()}<div class="section-grid"><div class="panel">${cards.map(([a,b])=>`<div class="panel-head"><div><b>${a}</b><div class="muted">${b}</div></div><button class="btn" data-action="report">Сформировать</button></div>`).join('')}</div><div class="panel"><div class="panel-head"><h2 class="section-title">Месячная выгрузка</h2></div><div class="report-box"><p>Форма, похожая на действующий Excel: дни, недели, часы, начисления, выплаты и остаток.</p><button class="btn primary" data-action="monthly-report">Сформировать Excel</button></div></div></div>`}

function openDrawer(id){const s=state.shifts.find(x=>x.id===id),p=person(s.personId),drawer=document.querySelector('#drawer');drawer.innerHTML=`<div class="drawer-head"><div><h2>Смена ${s.date}</h2><span class="demo-badge">${modeLabel(true)}</span><h3>${p.name}</h3><div class="muted">${s.workshop?`${s.workshop} · `:''}${s.position} · ${s.type} · ${employment(s)}</div></div><button class="icon-btn" data-close-drawer>×</button></div><div class="drawer-section"><h3>Площадка и плательщик</h3><div class="calc-row"><span>${s.location}</span><strong>${s.legalEntity||'Не указано'}</strong></div>${p.patent?'<span class="tag green">Патент есть</span>':'<span class="tag">Патент не указан</span>'}</div><div class="drawer-section"><h3>Три слоя времени</h3><div class="time-card"><div><span class="muted">Факт охраны</span><strong>${s.entry}–${s.exit||'…'}</strong></div><span>→</span><div><span class="muted">Рабочее</span><strong>${s.workStart?`${s.workStart}–${s.workEnd}`:'—'}</strong></div></div><div class="calc-row"><span>Оплачиваемое</span><strong>${hours(s)==null?'—':`${hours(s)} ч`}</strong></div></div><div class="drawer-section"><h3>Расчёт</h3><div class="calc-row"><span>Оформление этой смены</span><strong>${employment(s)}</strong></div><div class="calc-row"><span>Ставка</span><strong>${money(rateOf(s))} ${s.rateReview?'<span class="tag amber">На проверке</span>':''}</strong></div><div class="calc-row"><span>Начислено</span><strong>${money(accrued(s))}</strong></div><div class="calc-row"><span>Выдано</span><strong>${money(s.paid)}</strong></div><button class="btn" data-action="edit-rate" data-id="${p.id}">Настроить оформление и ставку</button></div><div class="drawer-section"><h3>История</h3>${state.audit.filter(a=>a.text.includes(p.name)).map(a=>`<p><b>${a.at}</b> · ${a.text} (${a.actor})</p>`).join('')||'<p class="muted">Изменений пока нет</p>'}</div><div class="drawer-actions"><button class="btn" data-action="request" data-id="${s.id}">Запросить корректировку</button><button class="btn primary" data-action="accept" data-id="${s.id}">${s.rateReview?'Подтвердить ставку':'Принять'}</button></div>`;showDrawer(drawer)}
function showDrawer(drawer){drawer.classList.remove('hidden');document.querySelector('#drawer-backdrop').classList.remove('hidden');drawer.querySelector('[data-close-drawer]').onclick=closeDrawer;drawer.querySelectorAll('[data-action]').forEach(bindAction)}
function openPersonDrawer(id){const p=person(id),r=personWeek(p),drawer=document.querySelector('#drawer'),locations=[...new Set(r.shifts.map(s=>s.location).filter(Boolean))],history=state.audit.filter(a=>a.text.includes(p.name)),adjustments=state.adjustments.filter(a=>a.personId===p.id);drawer.classList.add('person-drawer');drawer.innerHTML=`<div class="drawer-head"><div><div class="eyebrow">Карточка сотрудника</div><h2>${p.name}</h2><div class="muted">${p.position} · ${p.type} · ${employment(p)}</div></div><button class="icon-btn" data-close-drawer>×</button></div><div class="person-summary"><div><span>Часы</span><b>${r.shifts.reduce((n,s)=>n+(hours(s)||0),0)} ч</b></div><div><span>Начислено</span><b>${money(r.total)}</b></div><div><span>Остаток</span><b>${money(r.balance)}</b></div></div><div class="drawer-section"><div class="section-heading"><h3>Табель смен</h3><button class="btn small" data-action="edit-rate" data-id="${p.id}">Оформление и ставка</button></div>${r.shifts.length?`<div class="table-wrap person-shifts"><table class="data-table compact"><thead><tr><th>Дата</th><th>Площадка</th><th>Должность</th><th>Тип</th><th>Оформление</th><th>Присутствие</th><th>Рабочее время</th><th>К оплате</th><th>Ставка</th><th>Начислено</th><th>Выплачено</th><th>Статус</th></tr></thead><tbody>${r.shifts.map(s=>`<tr class="clickable" data-shift="${s.id}"><td>${s.date}</td><td>${s.location||'—'}</td><td>${s.position}</td><td>${s.type}</td><td>${employment(s)}</td><td>${s.entry}–${s.exit||'…'}</td><td>${s.workStart?`${s.workStart}–${s.workEnd}`:'—'}</td><td>${hours(s)==null?'—':`${hours(s).toLocaleString('ru-RU')} ч`}</td><td>${money(rateOf(s))}</td><td>${money(accrued(s))}</td><td>${money(s.paid)}</td><td>${status(s.status,tone(s))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Смен пока нет</p>'}<div class="location-list">${locations.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><div class="drawer-section"><div class="section-heading"><h3>Премии, анимации и штрафы</h3></div><div class="adjustment-actions"><button class="btn small" data-action="person-adjustment" data-type="Премия" data-id="${p.id}">+ Премия</button><button class="btn small" data-action="person-adjustment" data-type="Анимация" data-id="${p.id}">+ Анимация</button><button class="btn small danger" data-action="person-adjustment" data-type="Штраф" data-id="${p.id}">− Штраф</button></div>${adjustments.map(a=>`<div class="adjustment-line"><span><b>${a.type}</b><small>${a.type==='Штраф'?a.date||'Дата не указана':a.month} · ${a.location}${a.reason?` · ${a.reason}`:''}</small></span><strong class="${a.type==='Штраф'?'negative':'positive'}">${a.type==='Штраф'?'−':'+'}${money(a.amount)}</strong></div>`).join('')||'<p class="muted">Корректировок нет</p>'}</div><div class="drawer-section"><h3>История оформления и изменений</h3><div class="history-card"><p><b>Сейчас:</b> ${employment(p)} · ${p.type}</p><p class="muted">Изменение оформления действует с указанной даты; старые смены сохраняют прежние условия.</p></div>${history.map(a=>`<p><b>${a.at}</b> · ${a.text} (${a.actor})</p>`).join('')||'<p class="muted">История появится после первого изменения</p>'}</div><div class="drawer-section"><h3>Авансы и частичные выплаты</h3><button class="btn" data-action="person-payment" data-id="${p.id}">+ Зафиксировать выплату</button></div>`;showDrawer(drawer)}
function openCompactPersonDrawer(id){const p=person(id),r=personWeek(p),drawer=document.querySelector('#drawer'),history=state.audit.filter(a=>a.text.includes(p.name)),adjustments=state.adjustments.filter(a=>a.personId===p.id),totalHours=r.shifts.reduce((n,s)=>n+(hours(s)||0),0),netAdjustments=r.taxi+r.bonus-r.penalty,personStatus=r.errorShifts.length?status('Есть ошибки','bad'):r.balance>0?status('К выплате','warn'):status('Расчёт закрыт','good'),adjustmentNote=a=>a.type==='Штраф'?'Включено в период даты штрафа':a.month===periodMonth()?(isClosingPeriod()?'Включено в выбранную неделю':'Будет начислено в последнюю неделю месяца'):'Относится к другому месяцу';drawer.classList.add('person-drawer');drawer.innerHTML=`<div class="drawer-head compact-person-head"><div><div class="eyebrow">Карточка сотрудника</div><h2>${p.name}</h2><div class="person-identity"><span>${p.position}</span><span>${p.type}</span><span>${employment(p)}</span>${p.patent?'<span>Патент есть</span>':''}</div></div><div class="person-head-side">${personStatus}<button class="icon-btn" data-close-drawer aria-label="Закрыть">×</button></div></div><div class="person-summary compact-summary"><div><span>Часы</span><b>${totalHours.toLocaleString('ru-RU')} ч</b></div><div><span>Труд</span><b>${money(r.base)}</b></div><div><span>Такси и корректировки</span><b class="${netAdjustments<0?'negative':netAdjustments>0?'positive':''}">${netAdjustments>0?'+':''}${money(netAdjustments)}</b></div><div><span>Выплачено</span><b>${money(r.paid)}</b></div><div class="summary-balance"><span>Остаток</span><b>${money(r.balance)}</b></div></div>${r.plannedBonus>0&&!isClosingPeriod()?`<div class="person-callout"><b>${money(r.plannedBonus)} запланировано</b><span>Премии и анимации попадут в последнюю неделю ${periodMonth().toLowerCase()}.</span></div>`:''}<div class="drawer-section compact-section"><div class="section-heading"><div><h3>Смены</h3><span class="section-caption">${r.shifts.length} ${r.shifts.length===1?'смена':'смены'} · нажмите для подробностей</span></div></div><div class="person-shift-list">${r.shifts.length?r.shifts.slice().sort((a,b)=>b.date.localeCompare(a.date,'ru')).map(s=>`<button class="person-shift-card" data-action="open-person-shift" data-id="${s.id}"><span class="shift-date"><b>${s.date}</b><small>${s.location||'—'} · ${s.workshop?`${s.workshop} · `:''}${s.position}</small></span><span class="shift-terms"><span class="tag">${employment(s)}</span>${s.type==='Вызывной'?'<span class="tag amber">Вызывной</span>':''}</span><span class="shift-hours"><b>${hours(s)==null?'—':`${hours(s).toLocaleString('ru-RU')} ч`}</b><small>${s.workStart?`${s.workStart}–${s.workEnd}`:`${s.entry}–${s.exit||'…'}`}</small></span><span class="shift-money"><b>${money(accrued(s))}</b>${status(s.status,tone(s))}</span><span class="shift-arrow">›</span></button>`).join(''):empty('Смен пока нет','Данные появятся после отметки охраны.')}</div></div><div class="drawer-section compact-section"><div class="section-heading adjustments-heading"><div><h3>Премии, анимации и штрафы</h3><span class="section-caption">Корректировки начисления</span></div><div class="adjustment-actions"><button class="btn small" data-action="person-adjustment" data-type="Премия" data-id="${p.id}">+ Премия</button><button class="btn small" data-action="person-adjustment" data-type="Анимация" data-id="${p.id}">+ Анимация</button><button class="btn small danger" data-action="person-adjustment" data-type="Штраф" data-id="${p.id}">− Штраф</button></div></div>${adjustments.length?`<div class="adjustment-list">${adjustments.map(a=>`<div class="adjustment-line compact-adjustment"><span><b>${a.type}</b><small>${a.type==='Штраф'?a.date||'Дата не указана':a.month} · ${a.location}${a.reason?` · ${a.reason}`:''}</small><em>${adjustmentNote(a)}</em></span><strong class="${a.type==='Штраф'?'negative':'positive'}">${a.type==='Штраф'?'−':'+'}${money(a.amount)}</strong></div>`).join('')}</div>`:'<p class="muted compact-empty">Корректировок нет</p>'}</div><div class="drawer-section compact-section"><div class="current-terms"><span><small>Текущие условия</small><b>${employment(p)} · ${p.type}</b></span><span><small>Ставка сотрудника</small><b>${money(p.rate)}</b></span></div>${history.length?`<details class="history-details"><summary>История оформления и изменений <span>${history.length}</span></summary><div class="history-list">${history.map(a=>`<p><b>${a.at}</b><span>${a.text}</span><small>${a.actor}</small></p>`).join('')}</div></details>`:'<div class="history-empty">Изменений оформления пока нет</div>'}</div><div class="drawer-actions compact-person-actions"><button class="btn" data-action="edit-rate" data-id="${p.id}">Оформление и ставка</button><button class="btn primary" data-action="person-payment" data-id="${p.id}">Зафиксировать выплату</button></div>`;showDrawer(drawer)}
