function openRegistersModal(){const selected=[...document.querySelectorAll('[data-pay-person]:checked')].map(x=>Number(x.dataset.payPerson)),alreadyRegistered=personId=>state.registries.some(x=>x.status!=='Выплачен'&&x.people?.includes(personId)&&(x.accountingMonth||monthKeyFromRuDate(x.to))===currentAccountingMonthKey()),eligible=weekRows().filter(r=>r.ok&&r.balance>0&&!alreadyRegistered(r.p.id)&&(selected.length?selected.includes(r.p.id):true));if(!eligible.length){toast('Нет выбранных сотрудников: проверьте остаток и незакрытые ведомости');return}const groups=['ТК','СЗ','Наличные'];const m=document.querySelector('#modal');m.innerHTML=`<div class="modal-head"><div><h2>Массовая выплата</h2><div class="muted">PLUM сформирует отдельные ведомости по типам оформления</div></div><button class="icon-btn" data-close-modal>×</button></div><div class="batch-list">${groups.map(g=>{const rs=eligible.filter(r=>employment(r.p)===g),sum=rs.reduce((n,r)=>n+Math.max(0,r.balance),0);return `<section class="batch-group"><div><span class="tag green">${g}</span><b>${rs.length} сотрудников</b><small>Получатель: ${{'ТК':'Вероника','СЗ':'Дина','Наличные':'Наиля'}[g]}</small></div><strong>${money(sum)}</strong>${rs.map(r=>`<label class="batch-person"><span>${r.p.name}</span><input data-batch-amount="${r.p.id}" value="${Math.max(0,r.balance)}" type="number" min="0" step="100"><i>₽</i></label>`).join('')||'<p class="muted">Нет готовых выплат</p>'}</section>`}).join('')}</div><div class="notice"><span>Ошибочные сотрудники и уже включённые в незакрытую ведомость исключены. Сумма фиксируется при формировании.</span></div><div class="modal-actions"><button class="btn" data-close-modal>Отмена</button><button class="btn primary" data-create-registers>Сформировать ведомости</button></div>`;m.classList.remove('hidden');document.querySelector('#modal-backdrop').classList.remove('hidden');m.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModal);m.querySelector('[data-create-registers]').onclick=()=>{let created=0;groups.forEach(g=>{const rs=eligible.filter(r=>employment(r.p)===g);if(!rs.length)return;const items=rs.map(r=>({personId:r.p.id,amount:Number(m.querySelector(`[data-batch-amount="${r.p.id}"]`)?.value)})).filter(item=>Number.isFinite(item.amount)&&item.amount>0),amount=items.reduce((n,item)=>n+item.amount,0);if(!items.length)return;state.registries.unshift({id:nextId(),engagement:g,period:currentPeriod,from:isoToRu(currentPeriodFrom),to:isoToRu(currentPeriodTo),accountingMonth:currentAccountingMonthKey(),people:items.map(item=>item.personId),items,amount,recipient:{'ТК':'Вероника','СЗ':'Дина','Наличные':'Наиля'}[g],author:'Диля',status:'В реестре'});created++});if(!created){toast('Введите хотя бы одну сумму больше нуля');return}save();closeModal();currentView='registers';render();toast(`Сформировано ведомостей: ${created}`)}}
function closeDrawer(){const drawer=document.querySelector('#drawer');drawer.classList.add('hidden');drawer.classList.remove('person-drawer','security-person-drawer');document.querySelector('#drawer-backdrop').classList.add('hidden')}
function field(label,name,value='',type='text',full=false){const dateField=type==='date'||['date','from','to'].includes(name),dateFormat=type==='date'?'iso':'ru',displayValue=dateField&&/^\d{4}-\d{2}-\d{2}$/.test(value)?isoToRu(value):value,readonly=['display','calculated','lockedLocation','lockedEntity'].includes(name);return `<label class="field ${full?'full':''} ${dateField?'plum-date-field':''}">${label}<input data-field="${name}" type="${dateField?'text':type}" value="${displayValue}" ${dateField?`data-plum-date data-date-format="${dateFormat}" inputmode="numeric" placeholder="ДД.ММ.ГГГГ" autocomplete="off"`:''} ${readonly?'readonly':''}>${dateField?`<button type="button" class="date-picker-trigger" data-date-picker aria-label="Выбрать дату: ${label}" title="Открыть календарь"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></svg></button>`:''}</label>`}
function selectField(label,name,values,full=false){return `<label class="field ${full?'full':''}">${label}<select data-field="${name}">${values}</select></label>`}
function openModal(title,body,confirm='Сохранить',onConfirm=null){const m=document.querySelector('#modal');m.innerHTML=`<div class="modal-head"><div><h2>${title}</h2><span class="demo-badge">${modeLabel()}</span></div><button class="icon-btn" data-close-modal>×</button></div><div class="form-grid">${body}</div><div class="modal-actions"><button class="btn" data-close-modal>Отмена</button><button class="btn primary" data-confirm-modal>${confirm}</button></div>`;m.classList.remove('hidden');document.querySelector('#modal-backdrop').classList.remove('hidden');m.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModal);m.querySelector('[data-confirm-modal]').onclick=()=>{const data={};m.querySelectorAll('[data-field]').forEach(el=>{const value=el.type==='checkbox'?el.checked:el.value;data[el.dataset.field]=el.dataset.dateFormat==='iso'&&value?ruToIso(value):value});if(onConfirm&&onConfirm(data)===false)return;closeModal();save();render();toast('Действие сохранено')}}
function normalizedPersonName(value){return String(value||'').trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/\s+/g,' ')}
function normalizedPhone(value){let digits=String(value||'').replace(/\D/g,'');if(digits.length===10)digits=`7${digits}`;if(digits.length===11&&digits.startsWith('8'))digits=`7${digits.slice(1)}`;return digits}
function duplicatePerson(name,phone){const normalizedName=normalizedPersonName(name),normalizedNumber=normalizedPhone(phone);if(!normalizedName||normalizedNumber.length<10)return null;return state.people.find(p=>normalizedPersonName(p.name)===normalizedName&&normalizedPhone(p.phone)===normalizedNumber)||null}
function openRegisterPersonModal(){
 let modal,warning,nameInput,phoneInput;
 const showDuplicate=duplicate=>{if(!warning)return;if(duplicate){warning.classList.remove('hidden');warning.querySelector('[data-duplicate-person]').textContent=`${duplicate.name} · ${duplicate.phone||'номер не указан'}`;nameInput?.classList.add('duplicate-input');phoneInput?.classList.add('duplicate-input');nameInput?.setAttribute('aria-invalid','true');phoneInput?.setAttribute('aria-invalid','true')}else{warning.classList.add('hidden');nameInput?.classList.remove('duplicate-input');phoneInput?.classList.remove('duplicate-input');nameInput?.removeAttribute('aria-invalid');phoneInput?.removeAttribute('aria-invalid')}};
 openModal('Новый сотрудник',field('ФИО','name')+field('Телефон','phone')+`<div class="person-duplicate-warning hidden" data-person-duplicate-warning role="alert"><span class="person-duplicate-icon">!</span><span><b>Такой сотрудник уже зарегистрирован</b><small data-duplicate-person></small><em>Повторная карточка создана не будет.</em></span></div>`+field('Гражданство','citizenship')+field('Паспортные данные','passport','','text',true)+selectField('Должность','position',options(KITCHEN_POSITIONS))+`<label class="check-field full"><input data-field="patent" type="checkbox"><span><b>Патент есть</b><small>Необязательное поле</small></span></label><div class="field full rate-hint">Регистрация выполняется постом ${currentSecurityLocation}. Новый сотрудник автоматически регистрируется как штатный и с оформлением «Наличные».</div>`,'Зарегистрировать',d=>{const name=d.name.trim(),phone=d.phone.trim();if(!name){toast('Введите ФИО');return false}if(!phone){toast('Введите номер телефона');return false}if(normalizedPhone(phone).length<10){toast('Проверьте номер телефона');return false}const duplicate=duplicatePerson(name,phone);if(duplicate){showDuplicate(duplicate);toast('Сотрудник с таким ФИО и телефоном уже есть');return false}if(!d.citizenship.trim()){toast('Укажите гражданство');return false}if(!d.passport.trim()){toast('Укажите паспортные данные');return false}state.people.push({id:nextId(),name,phone,citizenship:d.citizenship.trim(),passport:d.passport.trim(),position:d.position,type:'Штатный',engagement:'Наличные',rate:null,patent:d.patent,source:'security',securityVisible:true,registeredAtLocation:currentSecurityLocation});state.audit.unshift({at:new Date().toLocaleString('ru-RU'),actor:`Охрана · ${currentSecurityLocation}`,text:`Зарегистрирован штатный сотрудник ${name} · оформление Наличные${d.patent?' · патент есть':''}`})});
 modal=document.querySelector('#modal');warning=modal.querySelector('[data-person-duplicate-warning]');nameInput=modal.querySelector('[data-field="name"]');phoneInput=modal.querySelector('[data-field="phone"]');const check=()=>showDuplicate(duplicatePerson(nameInput.value,phoneInput.value));nameInput.addEventListener('input',check);phoneInput.addEventListener('input',check);nameInput.focus()
}
function closeModal(){document.querySelector('#modal').classList.add('hidden');document.querySelector('#modal-backdrop').classList.add('hidden')}
